#                           goal: >   ...   backstory: >   ...

from crewai import Agent, Crew, Process, Task
from crewai.project import CrewBase, agent, crew, task

@CrewBase
class ResearchCrew:
    @agent
    def researcher(self) -> Agent:          # name matches the YAML key
        return Agent(config=self.agents_config["researcher"], verbose=True)

    @task
    def research_task(self) -> Task:
        return Task(config=self.tasks_config["research_task"])

    @crew
    def crew(self) -> Crew:
        return Crew(agents=self.agents, tasks=self.tasks, process=Process.sequential)

# main.py:  ResearchCrew().crew().kickoff(inputs={"topic": "AI LLMs"})

from crewai.tools import BaseTool, tool
from pydantic import BaseModel, Field

ORDERS = {"A-1001": "shipped", "A-1002": "processing"}

@tool("Order status lookup")
def order_status(order_id: str) -> str:
    """Return the shipping status for an order ID like 'A-1001'."""
    return ORDERS.get(order_id, f"No order {order_id}. IDs look like A-1001.")

class RefundInput(BaseModel):
    order_id: str = Field(description="Order ID, e.g. A-1001")
    amount: float = Field(gt=0, description="Refund amount in USD")

class RefundTool(BaseTool):
    name: str = "Request refund"
    description: str = "Create a refund request for a shipped order."
    args_schema: type[BaseModel] = RefundInput

    def _run(self, order_id: str, amount: float) -> str:
        return f"Refund of ${amount:.2f} requested for {order_id}."

print(order_status.run(order_id="A-1001"))            # shipped
print(RefundTool().run(order_id="A-1001", amount=20))  # Refund of $20.00 requested for A-1001.

concepts.body:
A **Flow** is a Python class whose methods are steps. Decorators (the `@name` lines above a method) say when each step runs:

- `@start()` marks an entry point. It runs when the flow starts.
- `@listen(step)` runs a method after `step` finishes. It receives that step's return value as an argument.

```python
class Pipeline(Flow):
    @start()
    def fetch(self):
        return "raw text"

    @listen(fetch)
    def clean(self, text):
        return text.strip()
```

`Pipeline().kickoff()` runs the flow and returns the output of the last step that finished.

**State** is data shared by all steps of one run. Two styles:

- Unstructured: `self.state` behaves like a dictionary: `self.state["count"] = 1`.
- Structured: subclass `Flow[MyState]`, where `MyState` is a Pydantic model (a class with typed, validated fields). Then use `self.state.count`. This catches typos and documents the data. Prefer it beyond toys.

Every run's state has a unique `id`, used later for saving and resuming.

You can pass values in with `kickoff(inputs={...})`; matching state fields are filled before the first step.

Steps can contain anything: plain code, a direct LLM call, `agent.kickoff(...)` for a single agent, or a whole crew. That is the point of flows: AI where you need it, normal code everywhere else.

`flow.plot("my_flow")` writes an HTML diagram of the steps, useful for reviews.

