from pydantic import BaseModel
from crewai.flow import Flow, listen, start

class TicketState(BaseModel):
    text: str = ""
    words: int = 0
    summary: str = ""

class TicketFlow(Flow[TicketState]):
    @start()
    def receive(self):
        self.state.words = len(self.state.text.split())
        return self.state.text

    @listen(receive)
    def summarize(self, text):
        # Replace with an agent or crew call in a real app
        self.state.summary = text[:40] + ("..." if len(text) > 40 else "")
        return self.state.summary

flow = TicketFlow()
out = flow.kickoff(inputs={"text": "My invoice for March shows a double charge, please fix."})
print(out)                # My invoice for March shows a double char...
print(flow.state.words)   # 10

from typing import Literal
from pydantic import BaseModel
from crewai.flow import Flow, and_, listen, or_, router, start

class S(BaseModel):
    amount: float = 0
    log: list[str] = []

class RefundFlow(Flow[S]):
    @start()
    def check_fraud(self):   self.state.log.append("fraud ok")
    @start()
    def check_stock(self):   self.state.log.append("stock ok")
    @router(and_(check_fraud, check_stock))      # wait for both checks
    def decide(self) -> Literal["auto", "review"]:
        return "auto" if self.state.amount < 100 else "review"

    @listen("auto")
    def approve(self):       self.state.log.append("approved")
    @listen("review")
    def escalate(self):      self.state.log.append("sent to human")
    @listen(or_(approve, escalate))               # either branch ends here
    def notify(self):        return " | ".join(self.state.log)

print(RefundFlow().kickoff(inputs={"amount": 250}))   # fraud ok | stock ok | sent to human

from pydantic import BaseModel
from crewai import Agent, Crew, Task
from crewai.flow import Flow, listen, start

def writing_crew() -> Crew:
    writer = Agent(role="Blog writer", goal="Write clear posts", backstory="Writes for engineers.")
    post = Task(description="Write a 150-word post about {topic}.", expected_output="Markdown.", agent=writer)
    return Crew(agents=[writer], tasks=[post])

class PostState(BaseModel):
    topic: str = ""
    draft: str = ""

class PostFlow(Flow[PostState]):
    @start()
    def validate(self):
        if not self.state.topic.strip():
            raise ValueError("topic is required")
    @listen(validate)
    def write(self):
        self.state.draft = writing_crew().kickoff(inputs={"topic": self.state.topic}).raw
    @listen(write)
    def publish(self): return f"{len(self.state.draft.split())} words ready"

print(PostFlow().kickoff(inputs={"topic": "Python virtual environments"}))

from pydantic import BaseModel
from crewai.flow import Flow, human_feedback, listen, persist, start

class EmailState(BaseModel):
    draft: str = ""
@persist()                                   # save state after each step (SQLite)
class EmailFlow(Flow[EmailState]):
    @start()
    @human_feedback(message="Send this email to the customer?",
                    emit=["approved", "rejected"], llm="openai/gpt-4o-mini",
                    default_outcome="rejected")
    def draft_email(self):
        self.state.draft = "Hi Sam, your refund was approved and sent today."
        return self.state.draft
    @listen("approved")
    def send(self):
        return f"sent: {self.state.draft}"
    @listen("rejected")
    def hold(self):
        return f"held for edits ({self.last_human_feedback.feedback})"

flow = EmailFlow()
print(flow.kickoff())          # asks in the terminal, then sends or holds
print(flow.state.id)           # keep this id to resume: kickoff(inputs={"id": ...})

from crewai.events import (BaseEventListener, CrewKickoffCompletedEvent,
                           TaskCompletedEvent, ToolUsageFinishedEvent)

class CostLogger(BaseEventListener):
    def setup_listeners(self, crewai_event_bus):
        @crewai_event_bus.on(TaskCompletedEvent)
        def on_task(source, event):
            print(f"[task] {event.task_name} done: {str(event.output)[:60]}")

        @crewai_event_bus.on(ToolUsageFinishedEvent)
        def on_tool(source, event):
            print(f"[tool] {event.tool_name}")

        @crewai_event_bus.on(CrewKickoffCompletedEvent)
        def on_done(source, event):
            print(f"[crew] {event.crew_name} finished, tokens: {event.total_tokens}")

cost_logger = CostLogger()   # create once, before any kickoff
